/**
 * SpecialOfferToast — Reusable special offer notification toast
 * 
 * Used on:
 * - Compare page (triggered by FluffCo review section scroll + 3s, or exit intent)
 * - Advertorial pages (triggered by shop section scroll + 3s, or exit intent)
 * 
 * Features:
 * - Quantity toggle (4+🎁 / 2) matching PDP sticky cart style
 * - Countdown timer (shared cookie with PDP)
 * - -XX% discount badge (PDP-style)
 * - Smart triggers: scroll to target section + delay, exit intent
 * - Dismissible with session memory
 */

import { useState, useEffect, useRef, useMemo, useCallback } from "react";
import { Clock, Gift, Tag, X } from "lucide-react";
import { useSharedCountdown } from "@/hooks/useSharedCountdown";

interface SpecialOfferToastProps {
  /** CSS selector or element ID to observe for scroll trigger */
  triggerElementId: string;
  /** Delay in ms after trigger element enters viewport before showing toast */
  triggerDelay?: number;
  /** Whether a sticky bar is currently visible (adjusts toast position) */
  hasStickyBar?: boolean;
  /** Optional: link base for CTA (default: "/?qty=") */
  ctaLinkBase?: string;
}

// Offer pricing data (matches PDP US_STANDARD_PRICING)
const OFFER_PACKS = {
  4: { price: 165.90, originalPrice: 489.90, perUnit: 41.48, savings: 324.00, discount: 66, bonus: true },
  2: { price: 109.90, originalPrice: 251.80, perUnit: 54.95, savings: 141.90, discount: 56, bonus: false },
} as const;

export function SpecialOfferToast({
  triggerElementId,
  triggerDelay = 3000,
  hasStickyBar = false,
  ctaLinkBase = "/?qty=",
}: SpecialOfferToastProps) {
  const countdown = useSharedCountdown();
  const [showNotification, setShowNotification] = useState(false);
  const [dismissed, setDismissed] = useState(false);
  const [selectedPack, setSelectedPack] = useState<4 | 2>(4);
  const triggeredRef = useRef(false);
  const scrollTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  const currentOffer = OFFER_PACKS[selectedPack];

  // Smart triggers: scroll to target section + delay, or exit intent
  useEffect(() => {
    if (dismissed) return;

    const handleScroll = () => {
      if (triggeredRef.current || dismissed) return;
      const el = document.getElementById(triggerElementId);
      if (el) {
        const rect = el.getBoundingClientRect();
        if (rect.top < window.innerHeight && rect.bottom > 0) {
          if (!scrollTimerRef.current) {
            scrollTimerRef.current = setTimeout(() => {
              if (!triggeredRef.current && !dismissed) {
                triggeredRef.current = true;
                setShowNotification(true);
              }
            }, triggerDelay);
          }
        } else {
          if (scrollTimerRef.current) {
            clearTimeout(scrollTimerRef.current);
            scrollTimerRef.current = null;
          }
        }
      }
    };

    const handleMouseLeave = (e: MouseEvent) => {
      if (triggeredRef.current || dismissed) return;
      if (e.clientY <= 0) {
        triggeredRef.current = true;
        setShowNotification(true);
      }
    };

    window.addEventListener('scroll', handleScroll, { passive: true });
    document.addEventListener('mouseleave', handleMouseLeave);

    return () => {
      window.removeEventListener('scroll', handleScroll);
      document.removeEventListener('mouseleave', handleMouseLeave);
      if (scrollTimerRef.current) clearTimeout(scrollTimerRef.current);
    };
  }, [dismissed, triggerElementId, triggerDelay]);

  const handleDismiss = useCallback(() => {
    setDismissed(true);
    setShowNotification(false);
  }, []);

  if (!showNotification || dismissed) return null;

  return (
    <>
      <div
        className={`fixed z-[45] transition-all duration-500 ease-out ${
          hasStickyBar ? 'bottom-[76px]' : 'bottom-4'
        } right-4 max-w-[340px] w-[calc(100vw-2rem)] sm:w-[340px] animate-[slideInUp_0.4s_ease-out_both]`}
      >
        <div className="bg-white rounded-xl shadow-2xl border border-gray-200 overflow-hidden">
          {/* Header with close button */}
          <div className="bg-[#424680] px-4 py-2.5 flex items-center justify-between">
            <div className="flex items-center gap-2">
              <Tag className="w-3.5 h-3.5 text-white/80" />
              <span className="text-xs font-semibold text-white">Exclusive Offer</span>
            </div>
            <button
              onClick={handleDismiss}
              className="text-white/60 hover:text-white transition-colors p-0.5"
              aria-label="Close offer notification"
            >
              <X className="w-3.5 h-3.5" />
            </button>
          </div>

          {/* Body */}
          <div className="p-4">
            {/* Quantity toggle — PDP-style pill selector */}
            <div className="flex items-center gap-1 rounded-full p-1 bg-gray-100 mb-3">
              <button
                onClick={() => setSelectedPack(4)}
                className={`flex-1 flex items-center justify-center gap-1 px-3 py-1.5 text-xs font-medium rounded-full transition-colors ${
                  selectedPack === 4
                    ? 'bg-[#424680] text-white'
                    : 'text-muted-foreground hover:text-foreground'
                }`}
              >
                4 +<Gift className="w-3 h-3" />
              </button>
              <button
                onClick={() => setSelectedPack(2)}
                className={`flex-1 px-3 py-1.5 text-xs font-medium rounded-full transition-colors ${
                  selectedPack === 2
                    ? 'bg-[#424680] text-white'
                    : 'text-muted-foreground hover:text-foreground'
                }`}
              >
                2
              </button>
            </div>

            {/* Offer details with -XX% badge */}
            <div className="flex items-start gap-3 mb-3">
              <div className="relative flex-shrink-0">
                <img src="/images/optimized/hero/hero-pillow.webp" alt="" className="w-12 h-12 rounded-lg object-cover" />
                {/* -XX% discount badge (PDP-style) */}
                <div className="absolute -top-1.5 -right-1.5 bg-[#e63946] text-white text-[9px] font-bold px-1.5 py-0.5 rounded-md shadow-sm">
                  -{currentOffer.discount}%
                </div>
              </div>
              <div className="min-w-0">
                <div className="text-sm font-semibold leading-tight">
                  {selectedPack} Pillows{selectedPack === 4 && ' + 2 Free Pillowcases'}
                </div>
                <div className="flex items-baseline gap-1.5 mt-1">
                  <span className="text-lg font-bold text-[#e63946]">${currentOffer.price.toFixed(2)}</span>
                  <span className="text-xs text-muted-foreground line-through">${currentOffer.originalPrice.toFixed(2)}</span>
                </div>
                <div className="text-[10px] text-muted-foreground mt-0.5">
                  ${currentOffer.perUnit.toFixed(2)}/pillow · Save ${currentOffer.savings.toFixed(2)}
                </div>
              </div>
            </div>

            {/* Timer */}
            <div className="flex items-center gap-1.5 text-xs text-muted-foreground mb-3">
              <Clock className="w-3 h-3" />
              <span>Offer ends in</span>
              <span className="font-semibold tabular-nums text-[#e63946]">
                {String(countdown.hours).padStart(2, '0')}:{String(countdown.minutes).padStart(2, '0')}:{String(countdown.seconds).padStart(2, '0')}
              </span>
            </div>

            {/* CTA */}
            <a
              href={`${ctaLinkBase}${selectedPack}`}
              className="block w-full text-center bg-[#e63946] hover:bg-[#d62839] text-white text-sm font-semibold py-2.5 rounded-full transition-colors"
            >
              Claim {currentOffer.discount}% Off
            </a>
          </div>
        </div>
      </div>

      {/* Slide-in animation */}
      <style>{`
        @keyframes slideInUp {
          from { opacity: 0; transform: translateY(20px); }
          to { opacity: 1; transform: translateY(0); }
        }
      `}</style>
    </>
  );
}

export default SpecialOfferToast;
